package caseapp

import caseapp.core.complete.Bash
import utest._

object BashCompletionTests extends TestSuite {

  private lazy val hasBash =
    !scala.util.Properties.isWin &&
    scala.util.Try(os.proc("bash", "-c", "true").call(check = false).exitCode == 0)
      .getOrElse(false)

  // Evaluates a snippet produced by Bash.print the way the function
  // generated by Bash.script does, and returns the resulting COMPREPLY
  private def bashReply(
    dir: os.Path,
    words: Seq[String],
    cword: Int,
    snippet: String
  ): Seq[String] = {
    val script =
      """IFS=$'\n'
        |snippet="$1"; cword="$2"; shift 2
        |COMP_WORDS=("$@"); COMP_CWORD="$cword"
        |eval "$snippet"
        |printf '%s\n' "${COMPREPLY[@]}"
        |""".stripMargin
    os.proc("bash", "-c", script, "bash", snippet, cword.toString, words)
      .call(cwd = dir)
      .out
      .lines()
      .filter(_.nonEmpty)
      .sorted
  }

  val tests = Tests {
    test("file fallback handles words starting with -") {
      if (hasBash) {
        val dir = os.temp.dir(prefix = "case-app-bash-test")
        try {
          for (name <- Seq("-foo", "-dir1", "bar"))
            os.write(dir / name, "")
          val snippet             = Bash.print(Nil)
          def reply(word: String) = bashReply(dir, Seq("prog", word), 1, snippet)

          assert(reply("-f") == Seq("-foo"))
          assert(reply("-X").isEmpty)
          assert(reply("--").isEmpty)
          assert(reply("-") == Seq("-dir1", "-foo"))
          assert(reply("b") == Seq("bar"))
        }
        finally os.remove.all(dir)
      }
      else
        "bash not available, skipped"
    }
  }
}
